-- Otomatik eşleşmede fotoğrafı çıkmayan 18 İstanbul yeri için elle seçilmiş Commons fotoğrafları.
-- Üreten: data-pipeline/content/build_photos_extra.py (kaynak: results/photo-candidates/candidates.json).
-- Mobil, fotoğrafın altında author ve license bilgisini göstermelidir (lisans koşulu).

delete from public.place_photos ph
using public.places p
where ph.place_id = p.id
  and ph.url like 'https://%.wikimedia.org/%'
  and p.slug in ('alemdag', 'anadolu-kavagi-manzara-seyir-noktasi', 'ayasofya-turbeleri', 'aziz-mahmud-hudayi-turbesi', 'bebek-parki', 'ciroz-plaji', 'fatih-sultan-mehmed-turbesi', 'i-abdulhamid-turbesi', 'kilyos-plaji', 'kucukcamlica-korusu', 'menekse-plaji', 'misir-carsisi', 'moda-sahili', 'nakkastepe-millet-bahcesi', 'otagtepe', 'sarayburnu-manzarasi', 'sultan-ahmed-turbesi', 'turhan-sultan-turbesi');

insert into public.place_photos
  (place_id, url, thumb_url, width, height, license, license_url, author, source_url, sort_order)
select p.id, v.url, v.thumb_url, v.width::int, v.height::int, v.license, v.license_url, v.author, v.source_url, 0
from (values
  ('alemdag', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/43/DSC_5009_Alemda%C4%9F_-_panoramio_%28cropped%29.jpg/1280px-DSC_5009_Alemda%C4%9F_-_panoramio_%28cropped%29.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/43/DSC_5009_Alemda%C4%9F_-_panoramio_%28cropped%29.jpg/500px-DSC_5009_Alemda%C4%9F_-_panoramio_%28cropped%29.jpg', 1280, 721, 'CC BY 3.0', 'https://creativecommons.org/licenses/by/3.0', 'hüsamettin_alpaslan', 'https://commons.wikimedia.org/wiki/File:DSC_5009_Alemda%C4%9F_-_panoramio_(cropped).jpg'),
  ('anadolu-kavagi-manzara-seyir-noktasi', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/69/Yoros_Castle_in_Anadolu_Kava%C4%9F%C4%B1_near_Istanbul_-_panoramio.jpg/1280px-Yoros_Castle_in_Anadolu_Kava%C4%9F%C4%B1_near_Istanbul_-_panoramio.jpg', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/6/69/Yoros_Castle_in_Anadolu_Kava%C4%9F%C4%B1_near_Istanbul_-_panoramio.jpg/500px-Yoros_Castle_in_Anadolu_Kava%C4%9F%C4%B1_near_Istanbul_-_panoramio.jpg', 1280, 960, 'CC BY-SA 3.0', 'https://creativecommons.org/licenses/by-sa/3.0', 'Modris Putns', 'https://commons.wikimedia.org/wiki/File:Yoros_Castle_in_Anadolu_Kava%C4%9F%C4%B1_near_Istanbul_-_panoramio.jpg'),
  ('ayasofya-turbeleri', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8c/II._Selim_T%C3%BCrbesi_2017-07-02_15.39.25_1791554687.JPG/1280px-II._Selim_T%C3%BCrbesi_2017-07-02_15.39.25_1791554687.JPG', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8c/II._Selim_T%C3%BCrbesi_2017-07-02_15.39.25_1791554687.JPG/500px-II._Selim_T%C3%BCrbesi_2017-07-02_15.39.25_1791554687.JPG', 1280, 853, 'CC BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 'Antonina Vyshnevska', 'https://commons.wikimedia.org/wiki/File:II._Selim_T%C3%BCrbesi_2017-07-02_15.39.25_1791554687.JPG'),
